-- =====================================================================
-- bus_map_20260729.sql   DATA -- loaded by action=load_run, NOT by migrate.
--
-- Bus assignment for the Chicago validator fleet: 4,218 devices, 1,832 distinct
-- buses. Source: validator_device_bus_serial_map.xlsx, supplied 29-Jul-2026.
--
-- WHY IT LIVES IN sql/load/ AND NOT IN migrate():
-- migrate() runs on EVERY deploy. A data INSERT there refills the table behind
-- your back after any purge, which is exactly the bug that made eight earlier
-- seed blocks impossible to clear. load_run is explicit and idempotent.
--
-- BUS_ID IS NOT ALWAYS PRESENT. Of 4,218 validators, only some carry a bus
-- assignment; the rest are spares, bench units or not yet fitted. Those rows
-- load with bus_id NULL rather than being dropped, so the dashboard can say
-- "not assigned to a bus" instead of silently losing the device.
-- =====================================================================
DELETE FROM dim_device_bus WHERE city_id = 'CHI';
